C = {}

# ---------- female.tex ----------
C["f587"] = r"""乳房手术对性健康的影响取决于手术动机与术式，需要分开讨论。出于乳腺癌治疗的重建手术与出于美观的整形手术，心理体验差异很大：前者常伴随"被疾病夺走一部分身体"的哀伤，性亲密的恢复需要处理被看见的恐惧与自我接纳；后者多与身体形象期待有关，术前对结果的预期越具体、越接近现实，术后满意度越高。感觉方面，采用神经保留技术的重建与部分缩乳手术可保留或部分恢复乳头的触觉与性反应，但并非人人如此，术前应向医生问清可能的感觉变化。
几点实用提醒：术前把"性感受是否会改变"作为必问项，而不是只谈外形；手术恢复期避免牵拉与压迫，遵循医嘱的恢复时间表；伴侣的参与方式应是询问与尊重，而不是评价"好看不好看"；有假体者仍需按医生建议进行筛查，假体不影响哺乳的证据有限，生育计划宜提前与医生讨论。"""

C["f3255"] = r"""首先需要清理术语：历史上的"慕男狂"（nymphomania）源自对女性性欲的道德化诊断，带有强烈的污名色彩，现代诊断体系已不再使用这一名称，"性欲亢进"本身也不是一个独立的确诊病名。临床关注的是现象背后的原因：性冲动与性行为频率显著高于个人可承受的程度，造成损害或失控感（如影响工作、财务、健康，或无法自控地寻求性行为）。
成因需要逐项排查：双相情感障碍的躁狂期、强迫症状、创伤后的再演（re-enactment）、某些药物（如多巴胺能药物）的影响，以及共病的物质使用。因此处理路径是先做精神科评估、再针对病因干预，而不是简单"压制欲望"。同时必须指出：性欲高于伴侣或高于社会平均值本身并不是病——只有当它带来痛苦或失控时，才构成需要帮助的问题。"""

C["f3497"] = r"""女性性功能障碍的物理治疗与康复是近年发展最快的领域之一，主要手段包括：盆底肌训练（凯格尔运动，配合生物反馈提高准确性）、盆底物理治疗（治疗师手法放松过度紧张的肌肉、处理扳机点）、电刺激与磁刺激（改善肌肉功能与血流）、阴道扩张器与触觉脱敏训练（用于痉挛与疼痛），以及针对产后与盆底术后的渐进康复方案。
它在性问题中的位置值得强调：许多被归为"心理"的问题其实有盆底肌肉的物理基础（过度紧张、协调不良、瘢痕黏连），单纯谈话治疗效果有限；反过来，物理治疗也需要配合心理干预才能持久。治疗通常以疗程计，8--12 周评估变化，需要耐心与配合。选择时建议寻找有女性盆底康复资质的医疗机构——产康中心、康复科或妇科盆底门诊都可作为入口。"""

C["f6594"] = r"""把解剖与生理放在一起理解，能得到比单看结构更多的信息。几个"结构—功能"的对应值得记住：阴蒂头神经末梢高度密集（约 8000 个）而位置在阴道口之外，这解释了为什么单纯插入常不足以带来高潮；阴道前壁与尿道、膀胱相邻，因此盆底肌状态与尿路症状会相互影响；卵巢与输卵管并非固定悬挂，而是有活动度的，这既解释了排卵痛的位置变化，也提示盆腔粘连为何会影响生育与性交痛；子宫位置（前倾/后倾）在正常范围内变异很大，多数与症状无关。
掌握这些对应关系对就医很有帮助：能准确描述"疼痛在哪里、什么时候痛、与月经和姿势的关系"，医生的判断效率会大幅提高；看懂一张盆腔示意图，也常能让女性对自己的身体少一分神秘与不安。"""

C["f8719"] = r"""前庭大腺（巴多林氏腺）位于阴道口两侧的腺体开口处，主要功能是在性唤起时分泌少量黏液以润滑阴道入口。它的临床意义主要有两个：其一是巴多林氏腺囊肿——腺管口堵塞后形成无痛或有压痛的小囊性肿物，多数无需处理，若反复感染或增大可考虑造口引流；其二是巴多林氏腺脓肿——感染后红肿疼痛明显，通常需要切开引流配合抗生素，急性期避免挤压自行处理。
需要与它区分的是外阴前庭痛（provoked vestibulodynia）：后者表现为触碰前庭区域时的烧灼样疼痛，并非肿块，治疗方向是盆底物理治疗与脱敏，与囊肿的处理完全不同。若在外阴摸到肿块或出现持续的接触性疼痛，就诊时明确说明"是肿块痛还是接触痛"，对诊断很有帮助。"""

C["f19764"] = r"""女性生殖器切割（FGM）指非医疗目的切除或损伤女性外生殖器的行为，世界卫生组织将其分为四型，从切除阴蒂包皮到最广泛的切除与缝合（infibulation）不等。它带来一系列健康后果：手术当时的出血、感染与死亡风险；长期可致慢性疼痛、反复感染、性交疼痛、性功能障碍；分娩时撕裂与难产风险显著增加，新生儿并发症与死亡率上升；心理层面常伴随创伤后应激症状。
在法律层面，联合国将其认定为侵犯人权的暴力行为，包括中国在内的众多国家已立法禁止，并禁止带女童出境实施。消除 FGM 的有效路径被证明包括社区教育、与宗教领袖和长者合作、把仪式以无害形式替代，以及提高女性教育与经济自主程度——只靠单一的刑事手段难以根除，但在保障每个女孩的身体完整上，法律的立场必须明确。"""

# ---------- male.tex ----------
C["m622"] = r"""前列腺素这个名字来自最初在精液中发现（研究者误以为来自前列腺），实际上它的功能远不止生殖：参与炎症、血管舒缩、子宫收缩与分娩启动等多个环节。在生殖方面，精液中的前列腺素可促进子宫颈与子宫的收缩、影响免疫微环境，理论上有助于精子通过女性生殖道；其与男性性功能的关系较为间接，主要通过炎症与血流环节参与慢性前列腺炎症状的形成。
临床上常被问到的两个问题值得澄清：一是"前列腺素药物会不会影响性功能"——用于引产或治疗的米索前列醇等属于医疗用药，与正常生理分泌量不在一个量级，短期使用后的影响通常可逆；二是"能不能靠补充前列腺素增强性功能"——目前没有任何证据支持这类补剂有效，相反，其血管与平滑肌作用可能带来不良反应，不建议自行服用。"""

C["m2166"] = r"""阴茎弯曲（Peyronie 病）的特征是阴茎白膜内形成纤维性斑块，导致勃起时明显弯曲、疼痛，部分患者出现长度缩短与勃起困难。病程常分两期：急性期（斑块仍在发展、疼痛明显，持续数月至一年余）与稳定期（斑块与弯曲固定）。处理方式依分期与严重程度而定：急性期以观察、口服或局部干预为主，并可考虑斑块内注射（如维拉帕米、胶原酶）以减少弯曲；稳定期且弯曲严重、影响性交者，可考虑手术矫形（折叠术、斑块切开加补片或假体植入）。
它对心理的影响常被低估：外观的变化与勃起疼痛足以造成焦虑、回避与关系紧张，而焦虑本身又会加重勃起困难。就医建议是早看泌尿外科男科门诊、记录弯曲角度与勃起状态的变化、不轻信"手法矫正"或"按摩溶解斑块"的说法——不当用力可能造成白膜损伤。"""

C["m2223"] = r"""精索静脉曲张指精索内静脉的异常扩张与迂曲，多见于左侧（解剖上左精索静脉回流路径更曲折），在成年男性中约占 15\%，在不育男性中比例明显更高。它影响生育的机制主要与阴囊内温度升高和静脉血返流产生的氧化应激有关，可导致精子浓度与活力下降、DNA 碎片率上升；临床上也常伴随阴囊坠胀与久站后的不适。
处理策略取决于是否有生育需求与症状：无症状且精液正常者可定期观察；精液异常或伴随明显症状者，可考虑显微外科结扎术——多项研究显示手术后精液参数改善、自然妊娠率与辅助生殖成功率提升。术后需要约 3 个月以上才能评估精液改善（一个生精周期约 74 天），期间继续避免久坐、高温环境与紧身内裤；若有生育计划，术后复查与辅助生殖的衔接应与医生提前商定。"""

C["m4107"] = r"""环境内分泌干扰物（EDCs）指能干扰体内激素合成、分泌、转运或作用的化学物质，与男性生殖健康关系较密切的包括双酚 A（BPA，见于部分塑料容器与收银小票）、邻苯二甲酸酯（塑料软化剂、香精溶剂）、部分农药与阻燃剂。研究提示这些物质与精子浓度下降、睾酮水平变化、隐睾与尿道下裂发生率上升存在关联；需要诚实说明的是，多数证据来自观察性研究与动物实验，个体层面的确切风险难以量化，但人群趋势已足以支持"减少暴露"的公共政策。
日常可行的减少暴露措施：避免用塑料容器加热食物，优先玻璃或不锈钢；减少使用含香精的个人护理品（尤其成分表中的 phthalate/parfum）；果蔬充分清洗、必要时去皮；新塑料用品通风一段时间再用；职业接触者（农药、涂料、印刷等）务必做好防护。这些建议对备孕男性尤有意义——精子生成周期约 3 个月，生活调整的收益也在同一时间尺度上显现。"""

C["m5259"] = r"""男性身体意象问题常以"肌肉畸形症"（muscle dysmorphia，俗称 bigorexia）的形式出现：即便体格已明显强壮，仍持续觉得自己"太瘦小"，进而出现无法停止的训练、严格的饮食控制、对体重与围度的反复测量，以及因错过一次训练而产生强烈焦虑。它属于躯体变形障碍的亚型，与进食障碍（尤其以增肌为目标的"暴食—清减"循环）关系密切。
需要特别警惕的是合成代谢类固醇的使用：为追求快速增肌而使用外源雄激素，可能带来痤疮、乳腺发育、睾丸萎缩、精子减少、血脂异常与情绪激动，并且常与他人的性功能下降相互纠缠（外源激素抑制自身分泌）。治疗方面，认知行为治疗是主要循证手段，共病的抑郁焦虑可用药物治疗；伴侣与健身房文化的影响也很关键——把"评价标准"从围度转向力量、恢复与整体健康，往往比单纯劝他"别练了"更有效。"""

C["m6644"] = r"""男性性感区的分布比多数人想象中更广：除阴茎（头、体、系带与尿道口周围）外，阴囊与睾丸、会阴与肛周（含前列腺可通过直肠间接刺激）、下腹与腹股沟、大腿内侧、乳头与胸肌，以及颈后与耳后等部位都可能具有敏感性。不同个体的敏感分布差异极大，且与情绪、放松程度、与伴侣的信任关系直接相关——紧张时这些区域会"变得不敏感"，这是神经系统而非技巧的问题。
实用的做法有三点：一是把探索当作双向的过程，双方各自找出"最舒服的三个位置"并可以随时更新；二是不追求"标准答案"，网络流传的"男性性感带地图"只是参考；三是注意舒适与安全——睾丸区域对压力敏感，力度需谨慎，肛周刺激必须充分润滑、缓慢并征得同意。把身体的敏感地图当作可以一起探索的区域而非固定的穴位，本身就是亲密的一部分。"""

